using System;
using System.Collections.Generic;
using System.Globalization;
using System.Linq;
using System.Threading;
using StockAnalyzer.Core.Analysis;
using StockAnalyzer.Core.Models;
using StockAnalyzer.Core.Models.Parameters;
using StockAnalyzer.TestSupport;
using static StockAnalyzer.TestSupport.CharacterizationSupport;
using Xunit;
using Xunit.Abstractions;

namespace StockAnalyzer.Core.Tests.Analysis;

/// <summary>
/// Characterization of <see cref="VolumeProfileViewportCalculator"/> and <see cref="TimeAtPriceViewportCalculator"/>: results of
/// valid requests (segments, POC/VAH/VAL, every bin) and the exact exception type and message of every rejected request.
/// The expected lines were captured before the shared calculation skeleton was extracted and must never be edited.
/// </summary>
public class ProfileViewportCalculatorCharacterizationTests
{
    private const int CandleCount = 20;
    private readonly ITestOutputHelper _output;

    public ProfileViewportCalculatorCharacterizationTests(ITestOutputHelper output)
    {
        _output = output;
    }

    private static List<CoreCandleData> Candles(long volumeBase = 1000)
    {
        var list = new List<CoreCandleData>();
        for (int i = 0; i < CandleCount; i++)
        {
            decimal open = 100.00m + (i % 7) * 1.25m;
            decimal close = open + ((i % 2 == 0) ? 0.75m : -0.50m);
            decimal high = Math.Max(open, close) + 0.40m + (i % 3) * 0.10m;
            decimal low = Math.Min(open, close) - 0.30m - (i % 4) * 0.05m;
            list.Add(new CoreCandleData(Ohlc8FirstDay.AddDays(i), open, high, low, close, volumeBase + i * 37L));
        }

        return list;
    }

    private static void Describe(List<string> lines, string label, Func<VolumeProfileViewportResult> run)
    {
        try
        {
            var result = run();
            lines.Add($"{label}|{result.RequestKey}|{result.Status}|segments={result.Segments.Count}");
            for (int s = 0; s < result.Segments.Count; s++)
            {
                var seg = result.Segments[s];
                string startDay = seg.StartTime.ToString("yyyy-MM-dd", CultureInfo.InvariantCulture);
                string endDay = seg.EndTime.ToString("yyyy-MM-dd", CultureInfo.InvariantCulture);
                lines.Add($"{label}|seg{s}|{seg.StartIndex}|{seg.Count}|{startDay}|{endDay}|{seg.IsPartial}|poc={Format(seg.POC)}|vah={Format(seg.VAH)}|val={Format(seg.VAL)}|bins={seg.Bins.Count}");
                for (int b = 0; b < seg.Bins.Count; b++)
                {
                    var bin = seg.Bins[b];
                    lines.Add($"{label}|seg{s}|bin{b}|{Format(bin.Price)}|{Format(bin.LowerBound)}|{Format(bin.UpperBound)}|{bin.TotalVolume}|{bin.BuyVolume}|{bin.SellVolume}|{BitConverter.DoubleToInt64Bits(bin.WidthPercent)}");
                }
            }
        }
        catch (Exception ex)
        {
            lines.Add($"{label}|EX|{ex.GetType().FullName}|{ex.Message}");
        }
    }

    private static List<string> Capture()
    {
        var lines = new List<string>();
        var windows = new[] { (0, 20), (5, 10), (15, 5) };

        foreach (int period in new[] { 0, 7 })
        {
            foreach (var mode in new[] { VolumeDistributionMode.Proportional, VolumeDistributionMode.Full })
            {
                foreach (var (start, count) in windows)
                {
                    var parameter = new CoreVolumeProfileParameter { Period = period, RowCount = 10, Mode = mode };
                    var candles = Candles();
                    Describe(lines, $"VP|p{period}|{mode}|{start}-{count}",
                        () => VolumeProfileViewportCalculator.Calculate("k", candles, start, count, TimeframeType.Daily, parameter));
                }
            }
        }

        var seriesFull = Candles().Select(c => (decimal?)(c.Close + 0.125m)).ToList();
        var seriesShort = seriesFull.Take(12).ToList();
        seriesShort[3] = null;

        foreach (int period in new[] { 0, 7 })
        {
            foreach (var (start, count) in windows)
            {
                foreach (var type in new[] { PriceType.Close, PriceType.Typical, PriceType.HeikinAshiClose })
                {
                    var parameter = new CoreTimeAtPriceParameter { Period = period, RowCount = 10, PriceType = type, PriceSource = type };
                    var candles = Candles();
                    Describe(lines, $"TAP|p{period}|{type}|{start}-{count}",
                        () => TimeAtPriceViewportCalculator.Calculate("k", candles, start, count, TimeframeType.Daily, parameter));
                    Describe(lines, $"TAPsrc|p{period}|{type}|{start}-{count}",
                        () => TimeAtPriceViewportCalculator.Calculate("k", candles, start, count, TimeframeType.Daily, parameter, null, type));
                }

                var seriesParameter = new CoreTimeAtPriceParameter { Period = period, RowCount = 10 };
                var seriesCandles = Candles();
                Describe(lines, $"TAPfull|p{period}|{start}-{count}",
                    () => TimeAtPriceViewportCalculator.Calculate("k", seriesCandles, start, count, TimeframeType.Daily, seriesParameter, seriesFull));
                Describe(lines, $"TAPshort|p{period}|{start}-{count}",
                    () => TimeAtPriceViewportCalculator.Calculate("k", seriesCandles, start, count, TimeframeType.Daily, seriesParameter, seriesShort));
            }
        }

        // Rejected and degenerate requests, both calculators.
        var vp = new CoreVolumeProfileParameter { Period = 0, RowCount = 10 };
        var tap = new CoreTimeAtPriceParameter { Period = 0, RowCount = 10 };

        var negative = Candles(); negative[8] = negative[8] with { Volume = -1 };
        var reversed = Candles(); reversed[8] = reversed[8] with { High = reversed[8].Low - 0.01m };
        var duplicate = Candles(); duplicate[8] = duplicate[8] with { Timestamp = duplicate[7].Timestamp };
        var unordered = Candles(); unordered[8] = unordered[8] with { Timestamp = unordered[2].Timestamp };
        var nullElement = new List<CoreCandleData>(Candles()); nullElement[8] = null!;
        var zeroVolume = Candles().Select(c => c with { Volume = 0 }).ToList();
        var cancelled = new CancellationToken(true);

        var cases = new (string Name, List<CoreCandleData> Data)[]
        {
            ("negativeVolume", negative), ("highBelowLow", reversed), ("duplicateTime", duplicate),
            ("unorderedTime", unordered), ("nullElement", nullElement), ("zeroVolume", zeroVolume),
            ("empty", new List<CoreCandleData>()),
        };

        foreach (var (name, data) in cases)
        {
            Describe(lines, $"VPbad|{name}", () => VolumeProfileViewportCalculator.Calculate("k", data, 0, 20, TimeframeType.Daily, vp));
            Describe(lines, $"TAPbad|{name}", () => TimeAtPriceViewportCalculator.Calculate("k", data, 0, 20, TimeframeType.Daily, tap));
        }

        var good = Candles();
        Describe(lines, "VPbad|visibleCountZero", () => VolumeProfileViewportCalculator.Calculate("k", good, 0, 0, TimeframeType.Daily, vp));
        Describe(lines, "TAPbad|visibleCountZero", () => TimeAtPriceViewportCalculator.Calculate("k", good, 0, 0, TimeframeType.Daily, tap));
        Describe(lines, "VPbad|parameterNull", () => VolumeProfileViewportCalculator.Calculate("k", good, 0, 20, TimeframeType.Daily, null!));
        Describe(lines, "TAPbad|parameterNull", () => TimeAtPriceViewportCalculator.Calculate("k", good, 0, 20, TimeframeType.Daily, null!));
        Describe(lines, "VPbad|cancelled", () => VolumeProfileViewportCalculator.Calculate("k", good, 0, 20, TimeframeType.Daily, vp, cancelled));
        Describe(lines, "TAPbad|cancelled", () => TimeAtPriceViewportCalculator.Calculate("k", good, 0, 20, TimeframeType.Daily, tap, cancelled));
        return lines;
    }

    [Fact]
    public void ProfileCalculators_MatchCapturedResults()
    {
        var actual = Capture();

        AssertMatches(Expected, actual, _output);
    }

